record.field:
template = tools.find("product.template", product_name, archived=True)
if not template:
    raise UserError("No existe el producto '%s'; créalo primero." % product_name)
lines, missing = [], []
for component in tools.lines(components):
    product = tools.find("product.product", component["name"], archived=True)
    if product:
        lines.append((0, 0, {"product_id": product.id, "product_qty": component["quantity"]}))
    else:
        missing.append(component["name"])
if missing:
    raise UserError("Componentes que no existen en el catálogo: %s" % ", ".join(missing))
bom = env["mrp.bom"].create({
    "product_tmpl_id": template.id,
    "product_qty": quantity or 1.0,
    "bom_line_ids": lines,
})
ai["result"] = {"model": "mrp.bom", "id": bom.id}

{
    "type": "object",
    "properties": {
        "product_name": {"type": "string"},
        "quantity": {"type": "number", "description": "Cantidad del producto que produce la lista"},
        "components": {
            "type": "array",
            "items": {"type": "string"},
            "description": "Un componente por línea con el formato 'producto | cantidad', p. ej. 'Glifosato 480 | 12.5'"
        }
    },
    "required": ["product_name", "components"]
}

product = tools.find("product.product", product_name)
if not product:
    raise UserError("No existe el producto '%s'." % product_name)
bom = env["mrp.bom"]._get_bom_by_product(product).get(product)
vals = {"product_id": product.id, "product_qty": quantity, "product_uom_id": product.uom_id.id, "origin": record._tool_origin()}
if bom:
    vals["bom_id"] = bom.id
if date_start:
    vals["date_start"] = tools.datetime(date_start, default_time="09:00", tz=record.user_id.tz or "America/Mexico_City")
production = env["mrp.production"].create(vals)
if note:
    record._tool_note(production, note)
ai["result"] = {"model": "mrp.production", "id": production.id}
